const $=id=>document.getElementById(id), esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const registry=window.GTM_DATA;let experiment,scene,grid=null,view='map',loadToken=0,syncing=false;const maps={},layers={},markers=[];
function allowedAsset(value){if(!value)return null;if(typeof value!=='string')throw Error('Asset must be a string');if(/^data:image\/(png|jpeg|webp);base64,/.test(value))return value;if(/^[\w./-]+$/.test(value)&&!value.includes('..')&&!value.startsWith('/'))return value;throw Error('Assets must be local relative paths or embedded PNG/JPEG/WebP images');}
function validateExperiment(e){if(!e||typeof e.id!=='string'||typeof e.name!=='string'||!Array.isArray(e.scenes))throw Error('Need experiment id, name and scenes');if(e.reportUrl)allowedAsset(e.reportUrl);if(e.scenes.length>1000)throw Error('Bundle exceeds 1,000 scenes');if(new Set(e.scenes.map(s=>s.id)).size!==e.scenes.length)throw Error('Duplicate scene IDs');for(const s of e.scenes){if(typeof s.id!=='string'||!Array.isArray(s.bounds)||s.bounds.length!==2||s.bounds.some(b=>!Array.isArray(b)||b.length!==2||b.some(v=>!Number.isFinite(v)))||s.bounds[0][0]>=s.bounds[1][0]||s.bounds[0][1]>=s.bounds[1][1]||s.bounds.some(b=>Math.abs(b[0])>85||Math.abs(b[1])>180))throw Error('Invalid scene bounds');['rgb','emit','truthImage','predictionImage','disagreementImage'].forEach(k=>allowedAsset(s[k]));if(s.grid&&typeof s.grid==='string')allowedAsset(s.grid);if(s.grid&&typeof s.grid!=='string')validateGrid(s.grid);else if(s.grid&&!/^[\w./-]+\.json$/.test(s.grid))throw Error('Invalid grid path');}return e;}
function validateGrid(g){const n=g.width*g.height;if(!Number.isInteger(g.width)||!Number.isInteger(g.height)||g.width<1||g.height<1||n<1||n>1048576)throw Error('Invalid display grid size');for(const key of ['probability','truth','valid']){if(g[key]&&(g[key].length!==n||g[key].some(v=>v!==null&&!Number.isFinite(v))))throw Error('Invalid '+key+' grid');}if(g.probability?.some(v=>v!==null&&(v<0||v>1)))throw Error('Probability outside [0,1]');if(g.truth?.some(v=>v!==null&&v!==0&&v!==1))throw Error('Truth mask must be 0/1/null');if(g.valid?.some(v=>v!==0&&v!==1))throw Error('Validity mask must be 0/1');return g;}
function hasPred(s){return !!(s.predictionImage||s.predictionAvailable||typeof s.grid==='object'&&s.grid.probability);}function text(id,v){$(id).textContent=v??'—';}
function initMap(id){const m=L.map(id,{zoomControl:false,zoomSnap:0.25,zoomDelta:0.5,maxZoom:20,minZoom:3}).setView([39,-98],4);L.control.zoom({position:'topright'}).addTo(m);L.control.scale({position:'bottomleft',imperial:false}).addTo(m);const satellite=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Imagery © Esri, Maxar, Earthstar Geographics and the GIS User Community'});const streets=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'});satellite.addTo(m);L.control.layers({'Satellite context':satellite,'Street context':streets},null,{position:'bottomright'}).addTo(m);layers[id]=[];maps[id]=m;return m;}
function overlay(id,url,opacity=1){if(!url||!scene)return;const l=L.imageOverlay(url,scene.bounds,{opacity,interactive:false}).addTo(maps[id]);layers[id].push(l);}
function clearLayers(){for(const id of Object.keys(maps)){layers[id].forEach(l=>maps[id].removeLayer(l));layers[id]=[];}}
function fit(){if(!scene)return;for(const m of Object.values(maps))m.fitBounds(scene.bounds,{padding:[20,20],maxZoom:17,animate:false});}
function updateURL(){const u=new URL(location.href);if(experiment)u.searchParams.set('experiment',experiment.id);if(scene)u.searchParams.set('scene',scene.id);else u.searchParams.delete('scene');u.hash=view;history.replaceState(null,'',u);}
function switchView(next){view=['map','compare','experiments'].includes(next)?next:'map';for(const v of ['map','compare','experiments'])$(v+'-view').hidden=v!==view;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view));});updateURL();setTimeout(()=>{Object.values(maps).forEach(m=>m.invalidateSize());if(scene)fit();},0);}
function selectExperiment(id){const previousScene=scene?.id;experiment=registry.experiments.find(e=>e.id===id)||registry.experiments[0];$('experiment').value=experiment.id;$('threshold').value=Number.isFinite(experiment.decisionThreshold)?experiment.decisionThreshold:0.5;text('context',experiment.name+' · '+experiment.status);$('search').value='';$('filter').value='all';drawList();selectScene(experiment.scenes.find(s=>s.id===previousScene)?.id||experiment.scenes[0]?.id);drawExperimentCards();}
function drawList(){const q=$('search').value.toLowerCase(),f=$('filter').value;const ss=experiment.scenes.filter(s=>(s.name+' '+s.id+' '+(s.location||'')).toLowerCase().includes(q)&&(f==='all'||f==='predictions'&&hasPred(s)||f==='paired'&&hasPred(s)&&(s.truthImage||s.grid)||f==='unscored'&&!hasPred(s)));$('scenes').innerHTML=ss.map(s=>`<button class="scene ${scene?.id===s.id?'active':''}" data-scene="${esc(s.id)}">${s.rgb?`<img src="${esc(s.rgb)}" alt="Observed scene thumbnail">`:''}<span><b>${esc(s.name)}</b><small>${esc(s.location||s.id)}</small><small>${esc(s.date||'Date not recorded')} · ${hasPred(s)?'Prediction':'Input only'}</small></span></button>`).join('');text('count',ss.length+' / '+experiment.scenes.length);$('no-scenes').hidden=ss.length>0;document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>selectScene(b.dataset.scene));}
function sourceCard(title,url,description){return `<div class="source">${url?`<img src="${esc(url)}" alt="${esc(title)}">`:'<div class="missing">—</div>'}<span><strong>${esc(title)}</strong><small>${esc(description)}</small></span></div>`;}
async function selectScene(id){const token=++loadToken;scene=experiment.scenes.find(s=>s.id===id)||null;grid=null;updateURL();drawList();markers.forEach(x=>maps['main-map'].removeLayer(x));markers.length=0;for(const s of experiment.scenes){const c=[(s.bounds[0][0]+s.bounds[1][0])/2,(s.bounds[0][1]+s.bounds[1][1])/2];const marker=L.circleMarker(c,{radius:5,color:'#fff',fillColor:'#008da1',fillOpacity:1,weight:2}).addTo(maps['main-map']).bindTooltip(s.name).on('click',()=>selectScene(s.id));markers.push(marker);}
if(!scene){clearLayers();for(const m of Object.values(maps))m.setView([39,-98],4,{animate:false});$('map-empty').hidden=false;text('map-empty','This experiment has saved aggregate results, but no aligned image/prediction exports available here. Open Experiments to inspect the evidence.');text('scene-title',experiment.name);text('scene-subtitle','No geographic prediction layer available');$('source-cards').innerHTML='';$('provenance').innerHTML='';text('limitations',experiment.notes);text('compare-notice','No geographic layers are available for this experiment.');renderGrid();return;}
$('map-empty').hidden=true;text('scene-title',scene.name);text('scene-subtitle',[scene.location,scene.date].filter(Boolean).join(' · '));$('source-cards').innerHTML=sourceCard('Sentinel-2',scene.rgb,scene.rgbNote||'Observed input; display contrast only')+sourceCard('EMIT reference',scene.emit,scene.emitNote||'Not available for this scene')+sourceCard(scene.truthLabel||'Reference mask',scene.truthImage,scene.truthNote||'No independent annotation available');const p={Model:experiment.name,Scene:scene.id,Date:scene.date,Reference:scene.referenceDate,Grid:scene.resolution,Source:scene.source,Checkpoint:scene.checkpointHash,Split:scene.split};$('provenance').innerHTML=Object.entries(p).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('');text('limitations',scene.notes||experiment.notes);text('compare-notice',scene.notes||experiment.notes);if(scene.grid){try{const loadedGrid=validateGrid(typeof scene.grid==='string'?await fetch(scene.grid).then(r=>{if(!r.ok)throw Error('Display grid missing');return r.json();}):scene.grid);if(token!==loadToken)return;grid=loadedGrid;}catch(e){if(token!==loadToken)return;grid=null;text('message',e.message);}}if(token!==loadToken)return;renderGrid();fit();}
function makeLayer(kind){if(!grid)return null;const c=document.createElement('canvas');c.width=grid.width;c.height=grid.height;const ctx=c.getContext('2d'),im=ctx.createImageData(c.width,c.height),threshold=+$('threshold').value;for(let i=0;i<c.width*c.height;i++){if(grid.valid&&!grid.valid[i])continue;const p=grid.probability?.[i],t=grid.truth?.[i];let rgb=null,a=0;if(kind==='prediction'&&p!=null&&p>=threshold){rgb=[255,135,35];a=110+Math.round(p*120);}if(kind==='truth'&&t===1){rgb=[0,225,230];const x=i%c.width,y=Math.floor(i/c.width);const edge=x===0||y===0||x===c.width-1||y===c.height-1||[i-1,i+1,i-c.width,i+c.width].some(j=>grid.truth[j]!==1);a=edge?245:45;}if(kind==='error'&&p!=null&&t!=null){if(p>=threshold&&t===1){rgb=[240,179,55];a=180;}else if(p>=threshold&&t===0){rgb=[247,71,122];a=215;}else if(p<threshold&&t===1){rgb=[152,121,240];a=215;}}if(rgb){im.data.set([...rgb,a],i*4);}}ctx.putImageData(im,0,0);return c.toDataURL();}
function renderGrid(){clearLayers();const pred=grid?.probability?makeLayer('prediction'):scene?.predictionImage,truth=grid?.truth?makeLayer('truth'):(scene?.truthImage||scene?.emit),errors=grid?.probability&&grid?.truth?makeLayer('error'):scene?.disagreementImage;const alpha=+$('opacity').value;text('prediction-status',pred?'Model output · threshold '+(+$('threshold').value).toFixed(2):'Prediction unavailable');text('reference-status',truth?(scene?.truthLabel||'Paired reference · not independent truth'):'Reference unavailable');for(const id of Object.keys(maps))if(scene)overlay(id,scene.rgb);if(scene){if($('pred-toggle').checked)overlay('main-map',pred,alpha);if($('truth-toggle').checked)overlay('main-map',truth,1);if($('error-toggle').checked)overlay('main-map',errors,alpha);overlay('prediction-map',pred,alpha);overlay('truth-map',errors||truth,alpha);if(errors)overlay('truth-map',truth,1);if($('bounds-toggle').checked)for(const id of Object.keys(maps))layers[id].push(L.rectangle(scene.bounds,{color:'#fff',dashArray:'5,5',weight:1,fill:false}).addTo(maps[id]));}
for(const [id,on] of [['pred-toggle',!!pred],['truth-toggle',!!truth],['error-toggle',!!errors],['threshold',!!grid?.probability]]){$(id).disabled=!on;}$('reset-threshold').disabled=!grid?.probability;text('threshold-value',(+$('threshold').value).toFixed(2));if(scene&&pred)text('compare-notice',scene.notes||experiment.notes);if(scene&&!pred)text('compare-notice','Prediction unavailable for this scene. These maps show the available observations and reference layers. '+(scene.notes||''));let tp=0,fp=0,fn=0,tn=0,n=0;if(grid?.probability&&grid?.truth)for(let i=0;i<grid.width*grid.height;i++){if(grid.valid&&!grid.valid[i]||grid.probability[i]==null||grid.truth[i]==null)continue;n++;const p=grid.probability[i]>=+$('threshold').value,t=grid.truth[i]===1;if(p&&t)tp++;else if(p)fp++;else if(t)fn++;else tn++;}const vals={TP:n?tp:null,FP:n?fp:null,FN:n?fn:null,TN:n?tn:null};$('pixel-metrics').innerHTML=Object.entries(vals).map(([k,v])=>`<div class="metric"><span>${k}</span><strong>${v??'—'}</strong></div>`).join('');text('metric-note',n?`${n.toLocaleString()} jointly valid display pixels. IoU ${tp+fp+fn?(tp/(tp+fp+fn)).toFixed(3):'undefined (no positives)'}. Exploratory agreement with this reference; not independent validation.`:'Pixel-level prediction and a valid reference mask are both required. No missing values are treated as negatives.');drawPlots();}
function drawPlots(){for(const id of ['histogram','profile']){const c=$(id),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#69808e';ctx.font='13px Segoe UI';if(!grid?.probability){ctx.fillText('Prediction raster not available',16,35);continue;}ctx.strokeStyle='#d4e0e6';ctx.beginPath();ctx.moveTo(30,10);ctx.lineTo(30,c.height-25);ctx.lineTo(c.width-12,c.height-25);ctx.stroke();if(id==='histogram'){const bins=Array(20).fill(0);grid.probability.forEach((p,i)=>{if(p!=null&&(!grid.valid||grid.valid[i]))bins[Math.min(19,Math.floor(p*20))]++;});const max=Math.max(...bins,1);ctx.fillStyle='#e99d3c';bins.forEach((v,i)=>ctx.fillRect(35+i*(c.width-55)/20,c.height-26-v/max*(c.height-45),(c.width-55)/20-3,v/max*(c.height-45)));ctx.fillStyle='#69808e';ctx.fillText('0',30,c.height-7);ctx.fillText('1 probability',c.width-92,c.height-7);}else{const y=Math.floor(grid.height/2);for(const [key,color] of [['probability','#e99632'],['truth','#009eaf']]){if(!grid[key])continue;ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();let started=false;for(let x=0;x<grid.width;x++){const i=y*grid.width+x,v=grid[key][i];if(v==null||grid.valid&&!grid.valid[i]){started=false;continue;}const px=30+x/(grid.width-1)*(c.width-45),py=c.height-25-v*(c.height-40);if(!started)ctx.moveTo(px,py);else ctx.lineTo(px,py);started=true;}ctx.stroke();}ctx.fillStyle='#69808e';ctx.fillText('0',12,c.height-25);ctx.fillText('1',12,17);ctx.fillText('Pixel position →',c.width-115,c.height-5);}}}
function drawExperimentCards(){$('experiments').innerHTML=registry.experiments.map(e=>`<article class="experiment-card"><div class="eyebrow">${esc(e.status)}</div><h2>${esc(e.name)}</h2><p>${esc(e.description||'')}</p>${e.metrics?`<table><thead><tr>${Object.keys(e.metrics).map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody><tr>${Object.values(e.metrics).map(v=>`<td>${esc(v)}</td>`).join('')}</tr></tbody></table>`:''}<p>${esc(e.notes)}</p><p class="readonly">${e.scenes.length} geographic scenes available · ${e.reportUrl?`<a href="${esc(allowedAsset(e.reportUrl))}">Evidence report ↗</a>`:esc(e.report||'Local export')}</p><button data-experiment="${esc(e.id)}">Open experiment</button></article>`).join('');document.querySelectorAll('[data-experiment]').forEach(b=>b.onclick=()=>{selectExperiment(b.dataset.experiment);switchView('map');});}
try{if(!window.L)throw Error('Map library could not load');if(!registry?.experiments?.length)throw Error('Experiment registry is missing');registry.experiments.forEach(validateExperiment);['main-map','original-map','prediction-map','truth-map'].forEach(initMap);for(const id of ['original-map','prediction-map','truth-map'])maps[id].on('moveend',()=>{if(syncing||!$('linked').checked)return;syncing=true;const m=maps[id];for(const other of ['original-map','prediction-map','truth-map'])if(other!==id)maps[other].setView(m.getCenter(),m.getZoom(),{animate:false});syncing=false;});$('experiment').innerHTML=registry.experiments.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('');document.querySelector('.brand').onclick=e=>{e.preventDefault();switchView('map');};$('experiment').onchange=()=>selectExperiment($('experiment').value);$('search').oninput=drawList;$('filter').onchange=drawList;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));for(const id of ['pred-toggle','truth-toggle','error-toggle','bounds-toggle','opacity','threshold'])$(id).oninput=renderGrid;$('reset-threshold').onclick=()=>{$('threshold').value=experiment.decisionThreshold??0.5;renderGrid();};$('fit').onclick=fit;$('overview').onclick=()=>{switchView('map');setTimeout(()=>maps['main-map'].setView([39,-98],4),25);};$('import').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;if(file.size>50*1024*1024)throw Error('Bundle exceeds 50 MiB');const parsed=JSON.parse(await file.text()),e=validateExperiment(parsed.experiment||parsed);if(registry.experiments.some(x=>x.id===e.id))throw Error('Experiment ID already exists');registry.experiments.push(e);const opt=document.createElement('option');opt.value=e.id;opt.textContent=e.name;$('experiment').append(opt);selectExperiment(e.id);text('message','Opened locally; nothing uploaded');}catch(e){text('message','Import failed: '+e.message);}finally{ev.target.value='';}};const query=new URLSearchParams(location.search),initialScene=query.get('scene'),initialView=location.hash.slice(1)||'map';selectExperiment(query.get('experiment')||registry.experiments[0].id);if(initialScene&&experiment.scenes.some(s=>s.id===initialScene))selectScene(initialScene);switchView(initialView);}catch(e){text('message',e.message);console.error(e);}
